// Seed of a sequential sum from +0: add(+0, x) = x for finite x, except that a
// negative zero (a BF16 term that rounded to -0) becomes +0.
module ot_hdc_v41x_idx_chunk_l #(
    parameter integer NB  = 4,        // 32-blocks per head (index_head_dim / 32)
    parameter integer NKT = 1,        // keys per cycle through this tile
    parameter integer HB  = 0,        // first head of this chunk (for the q-load port)
    parameter integer FPL = 3,        // binary32 add latency
    parameter integer FML = 3,        // head-weight product latency (ot_hdc_v41x_bmul_l)
    parameter integer QL  = 3         // block-dot latency (ot_hdc_v41x_q4dot_l)
) (
    input  wire                  clk,
    input  wire                  rst_n,
    // q load: one head per cycle
    input  wire                  ql_v,
    input  wire [7:0]            ql_head,
    input  wire [NB*128-1:0]     ql_codes,
    input  wire [NB*8-1:0]       ql_sc,
    input  wire [15:0]           ql_w,
    // keys
    input  wire                  k_v,
    input  wire [NKT-1:0]        k_kv,
    input  wire [NKT*NB*136-1:0] k_key,
    // chunk sums
    output reg                   c_v,
    output reg  [NKT-1:0]        c_kv,
    output reg  [NKT*32-1:0]     c_sum,
    output reg  [NKT-1:0]        c_fault
);
    localparam integer HC = 8;
    localparam integer KW = NB * 136;
    localparam integer LAT_SC = QL + FPL * (NB - 1);    // block dots + sequential block adds
    localparam integer LAT_T  = LAT_SC + 1 + FML;       // + bf16/ReLU + product
    localparam integer LAT    = LAT_T + FPL * (HC - 1); // + 7 sequential head adds

    // -- query registers (loaded between tokens) -----------------------------------
    reg [HC*NB*128-1:0] qc;
    reg [HC*NB*8-1:0]   qs;
    reg [HC*16-1:0]     qw;
    // A q-load beat is registered, its head decoded into a per-head write enable
    // and registered again with the data (a head's 553 query flops hang off one
    // registered enable, which repair buffers as a tree), then written: 2 cycles.
    reg              rql_v;
    reg [7:0]        rql_head;
    reg [NB*128-1:0] rql_codes, rq2_codes;
    reg [NB*8-1:0]   rql_sc, rq2_sc;
    reg [15:0]       rql_w, rq2_w;
    reg [HC-1:0]     rq2_we;
    integer hq;
    always @(posedge clk) begin
        rql_v <= ql_v && rst_n;
        rql_head <= ql_head;
        rql_codes <= ql_codes;
        rql_sc <= ql_sc;
        rql_w <= ql_w;
        for (hq = 0; hq < HC; hq = hq + 1)
            rq2_we[hq] <= rst_n && rql_v && (rql_head == HB + hq);
        rq2_codes <= rql_codes;
        rq2_sc <= rql_sc;
        rq2_w <= rql_w;
    end
    always @(posedge clk)
        for (hq = 0; hq < HC; hq = hq + 1)
            if (rq2_we[hq]) begin
                qc[hq*NB*128 +: NB*128] <= rq2_codes;
                qs[hq*NB*8 +: NB*8] <= rq2_sc;
                qw[hq*16 +: 16] <= rq2_w;
            end

    // -- input register ---------------------------------------------------------------
    reg              rv;
    reg [NKT-1:0]    rkv;
    reg [NKT*KW-1:0] rkey;
    always @(posedge clk) begin
        rv <= k_v && rst_n;
        rkv <= k_kv;
        rkey <= k_key;
    end

    // validity and per-key valid bits travel on a reset line
    wire [NKT:0] vl;
    ot_hdc_delay #(.W(NKT + 1), .D(LAT), .RESET(1)) u_vl (.clk(clk), .rst_n(rst_n), .d({rkv, rv}), .q(vl));

    genvar g, h, bb;
    generate
        for (g = 0; g < NKT; g = g + 1) begin : g_key
            wire [KW-1:0] key = rkey[g*KW +: KW];
            // key block i, skewed so its block dot meets the running sum
            wire [NB*128-1:0] kc;
            wire [NB*8-1:0]   ks;
            for (bb = 0; bb < NB; bb = bb + 1) begin : g_skew
                localparam integer DS = (bb == 0) ? 0 : FPL * (bb - 1);
                wire [135:0] kb_d;
                ot_hdc_delay #(.W(136), .D(DS)) u_sk (.clk(clk), .rst_n(rst_n),
                    .d({key[NB*128 + 8*bb +: 8], key[128*bb +: 128]}), .q(kb_d));
                assign kc[128*bb +: 128] = kb_d[127:0];
                assign ks[8*bb +: 8] = kb_d[135:128];
            end

            wire [HC*16-1:0] term;
            wire [HC-1:0]    tfault;
            for (h = 0; h < HC; h = h + 1) begin : g_head
                // block dots and the sequential block sum
                wire [NB*32-1:0] acc;
                wire [NB-1:0] afault;
                for (bb = 0; bb < NB; bb = bb + 1) begin : g_blk
                    wire [31:0] bv;
                    wire        bo;
                    ot_hdc_v41x_q4dot_l #(.QL(QL)) u_d (.clk(clk), .a(qc[(h*NB+bb)*128 +: 128]), .b(kc[128*bb +: 128]),
                                           .ua(qs[(h*NB+bb)*8 +: 8]), .ub(ks[8*bb +: 8]), .y(bv), .ovf(bo));
                    if (bb == 0) begin : g_first
                        assign acc[31:0] = bv;                 // add(+0, b0) = b0 (b0 is +0 or nonzero)
                        assign afault[0] = bo;
                    end else begin : g_add
                        wire [1:0] err;
                        wire       vo_unused;
                        wire       pf;                      // fault of the running sum, carried
                        ot_hdc_delay #(.W(1), .D(FPL)) u_pf (.clk(clk), .rst_n(rst_n), .d(afault[bb-1]), .q(pf));
                        ot_hdc_v41x_faddl #(.LAT(FPL)) u_a (.clk(clk), .rst_n(rst_n), .valid_in(1'b1),
                            .a(acc[32*(bb-1) +: 32]), .b(bv), .y(acc[32*bb +: 32]), .err(err), .valid_out(vo_unused));
                        // the block fault is FPL cycles younger than the sum it joins
                        wire bo_d;
                        ot_hdc_delay #(.W(1), .D(FPL)) u_bf (.clk(clk), .rst_n(rst_n), .d(bo), .q(bo_d));
                        assign afault[bb] = pf || bo_d || (err != 2'd0);
                    end
                end
                // score to BF16, ReLU is inside the product unit
                wire [15:0] sc16;
                wire        sco;
                ot_hdc_v41x_bf16 u_sb (.x(acc[32*(NB-1) +: 32]), .y(sc16), .ovf(sco));
                reg  [15:0] rsc;
                reg         rscf;
                always @(posedge clk) begin
                    rsc <= sc16;
                    rscf <= afault[NB-1] || sco;
                end
                wire [15:0] tm;
                wire        tmo;
                ot_hdc_v41x_bmul_l #(.ML(FML)) u_m (.clk(clk), .a(rsc), .w(qw[16*h +: 16]), .y(tm), .ovf(tmo));
                wire        rscf_d;
                ot_hdc_delay #(.W(1), .D(FML)) u_tf (.clk(clk), .rst_n(rst_n), .d(rscf), .q(rscf_d));
                assign term[16*h +: 16] = tm;
                assign tfault[h] = rscf_d || tmo;
            end

            // the chunk's sequential sum: seed with term 0 (-0 -> +0), then 7 adds;
            // term j joins at add j, FPL(j-1) cycles after the terms are formed
            wire [HC*32-1:0] cs;
            wire [HC-1:0] cf;
            assign cs[31:0] = (term[14:0] == 15'd0) ? 32'd0 : {term[15:0], 16'd0};
            assign cf[0] = tfault[0];
            for (h = 1; h < HC; h = h + 1) begin : g_chain
                wire [16:0] tj;
                ot_hdc_delay #(.W(17), .D(FPL * (h - 1))) u_tj (.clk(clk), .rst_n(rst_n),
                    .d({tfault[h], term[16*h +: 16]}), .q(tj));
                wire [1:0] err;
                wire       vo_unused;
                ot_hdc_v41x_faddl #(.LAT(FPL)) u_a (.clk(clk), .rst_n(rst_n), .valid_in(1'b1),
                    .a(cs[32*(h-1) +: 32]), .b({tj[15:0], 16'd0}), .y(cs[32*h +: 32]), .err(err), .valid_out(vo_unused));
                wire pf;
                ot_hdc_delay #(.W(1), .D(FPL)) u_pf (.clk(clk), .rst_n(rst_n), .d(cf[h-1] || tj[16]), .q(pf));
                assign cf[h] = pf || (err != 2'd0);
            end
            always @(posedge clk) begin
                c_sum[32*g +: 32] <= cs[32*(HC-1) +: 32];
                c_fault[g] <= cf[HC-1];
            end
        end
    endgenerate
    always @(posedge clk) begin
        c_v <= vl[0] && rst_n;
        c_kv <= vl[NKT:1];
    end
endmodule

// ---------------------------------------------------------------------------
// Per key: the pairwise tree over NCH chunk sums (NCH a power of two), to_bf16,
// the candidate mask (keep = 0 -> -inf), registered output.  LATENCY
// 1 + FPL log2(NCH) + 1.
// ---------------------------------------------------------------------------
module ot_hdc_v41x_idx_tail_l #(
    parameter integer NCH = 4,
    parameter integer NKT = 1,
    parameter integer FPL = 3          // binary32 add latency
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  i_v,
    input  wire [NKT-1:0]        i_kv,
    input  wire [NKT-1:0]        i_keep,
    input  wire [NKT*NCH*32-1:0] i_sum,     // key g, chunk c at [(g*NCH+c)*32 +: 32]
    input  wire [NKT*NCH-1:0]    i_fault,
    output reg                   o_v,
    output reg  [NKT-1:0]        o_kv,
    output reg  [NKT*16-1:0]     o_score,
    output reg  [NKT-1:0]        o_fault
);
    localparam integer LV = (NCH <= 1) ? 0 : $clog2(NCH);
    reg                  rv;
    reg [NKT-1:0]        rkv, rkeep;
    reg [NKT*NCH*32-1:0] rsum;
    reg [NKT*NCH-1:0]    rf;
    always @(posedge clk) begin
        rv <= i_v && rst_n;
        rkv <= i_kv;
        rkeep <= i_keep;
        rsum <= i_sum;
        rf <= i_fault;
    end
    wire [2*NKT:0] vl;
    ot_hdc_delay #(.W(2 * NKT + 1), .D(FPL * LV), .RESET(1)) u_vl (.clk(clk), .rst_n(rst_n),
        .d({rkeep, rkv, rv}), .q(vl));
    genvar g, l, i;
    generate
        for (g = 0; g < NKT; g = g + 1) begin : g_key
            // level l holds NCH >> l partial sums
            // level l, partial i at index l * NCH + i
            wire [(LV+1)*NCH*32-1:0] t;
            wire [(LV+1)*NCH-1:0]    tf;
            for (i = 0; i < NCH; i = i + 1) begin : g_in
                assign t[32*i +: 32] = rsum[(g * NCH + i) * 32 +: 32];
                assign tf[i] = rf[g * NCH + i];
            end
            for (l = 0; l < LV; l = l + 1) begin : g_lv
                for (i = 0; i < (NCH >> (l + 1)); i = i + 1) begin : g_add
                    wire [1:0] err;
                    wire       vo_unused;
                    ot_hdc_v41x_faddl #(.LAT(FPL)) u_a (.clk(clk), .rst_n(rst_n), .valid_in(1'b1),
                        .a(t[32*(l*NCH+2*i) +: 32]), .b(t[32*(l*NCH+2*i+1) +: 32]),
                        .y(t[32*((l+1)*NCH+i) +: 32]), .err(err), .valid_out(vo_unused));
                    wire pf;
                    ot_hdc_delay #(.W(1), .D(FPL)) u_pf (.clk(clk), .rst_n(rst_n),
                        .d(tf[l*NCH+2*i] || tf[l*NCH+2*i+1]), .q(pf));
                    assign tf[(l+1)*NCH+i] = pf || (err != 2'd0);
                end
            end
            wire [15:0] s16;
            wire        so;
            ot_hdc_v41x_bf16 u_b (.x(t[32*LV*NCH +: 32]), .y(s16), .ovf(so));
            always @(posedge clk) begin
                o_fault[g] <= tf[LV*NCH] || so;
                o_score[16*g +: 16] <= (tf[LV*NCH] || so) ? 16'd0 : (vl[1 + NKT + g] ? s16 : 16'hFF80);
            end
        end
    endgenerate
    always @(posedge clk) begin
        o_v <= vl[0] && rst_n;
        o_kv <= vl[NKT:1];
    end
endmodule

// ---------------------------------------------------------------------------
// The engine: NK keys per beat.
//
// Protocol.  Keys: valid/ready.  A beat (k_valid && k_ready) carries NK key
// slots; k_kv marks the slots holding a key (a scan's last beat may be
// partial), k_keep the candidate mask (1 = scored, 0 = -inf).  Scores:
// valid/ready, one beat per key beat, in key order, the same slots; o_fault
// per slot.  The datapath never stalls: k_ready is a credit test -- beats in
// flight plus beats held in the output FIFO stay within FD -- so with a
// consumer that is always ready the engine takes a beat every cycle, and a
// consumer that stalls backs the key stream up without losing a beat.  FD >=
// LATENCY + 2 sustains one beat per cycle; the engine deepens a smaller FD to
// the next power of two >= LATENCY + 2 (no change at FPL = FML = QL = 3, where
// LATENCY + 2 = 50 at NB = 4, IH = 32).  q load: ql_v, head index, codes,
// scales, BF16 weight; one head per cycle, before the keys it scores and after
// the previous token's keys have left the tile (k_ready holds keys off for 3
// cycles after the last q-load beat).
// ---------------------------------------------------------------------------
module ot_hdc_v41x_idx_engine_l #(
    parameter integer NK = 8,          // keys per cycle
    parameter integer IH = 32,         // index heads
    parameter integer NB = 4,          // 32-blocks per head
    parameter integer FD = 64,         // output FIFO depth (beats), at least
    parameter integer FPL = 3,         // binary32 add latency
    parameter integer FML = 3,         // head-weight product latency
    parameter integer QL  = 3          // block-dot latency
) (
    input  wire                 clk,
    input  wire                 rst_n,
    input  wire                 ql_v,
    input  wire [7:0]           ql_head,
    input  wire [NB*128-1:0]    ql_codes,
    input  wire [NB*8-1:0]      ql_sc,
    input  wire [15:0]          ql_w,
    input  wire                 k_valid,
    output wire                 k_ready,
    input  wire [NK-1:0]        k_kv,
    input  wire [NK-1:0]        k_keep,
    input  wire [NK*NB*136-1:0] k_key,
    output reg                  o_valid,
    input  wire                 o_ready,
    output reg  [NK-1:0]        o_kv,
    output reg  [NK*16-1:0]     o_score,
    output reg  [NK-1:0]        o_fault,
    // activation counters (since reset; for the benches): keys scored (score
    // slots delivered), head terms fused (ReLU x weight terms summed inside the
    // engine: IH per scored key), keys whose score faulted
    output reg  [47:0]          cnt_keys_scored,
    output reg  [47:0]          cnt_headsums_fused,
    output reg  [47:0]          cnt_faults
);
    localparam integer NCH = IH / 8;
    localparam integer LVT = (NCH <= 1) ? 0 : $clog2(NCH);
    localparam integer LAT_C = 1 + QL + FPL * (NB - 1) + 1 + FML + FPL * 7 + 1;   // chunk in-reg .. out-reg
    localparam integer LAT_T = 1 + FPL * LVT + 1;
    localparam integer LAT = LAT_C + LAT_T;                              // k beat -> tail output
    localparam integer FDE = (FD >= LAT + 2) ? FD : (1 << $clog2(LAT + 2));   // effective FIFO depth
    localparam integer CW = $clog2(FDE + 1);

    wire take = k_valid && k_ready;

    // chunks
    wire [NCH-1:0]        cv;
    wire [NK-1:0]         ckv [0:NCH-1];
    wire [NK*32-1:0]      csum [0:NCH-1];
    wire [NK-1:0]         cfl [0:NCH-1];
    genvar c, g;
    generate
        for (c = 0; c < NCH; c = c + 1) begin : g_ch
            ot_hdc_v41x_idx_chunk_l #(.NB(NB), .NKT(NK), .HB(8 * c), .FPL(FPL), .FML(FML), .QL(QL)) u_c (
                .clk(clk), .rst_n(rst_n), .ql_v(ql_v), .ql_head(ql_head), .ql_codes(ql_codes), .ql_sc(ql_sc),
                .ql_w(ql_w), .k_v(take), .k_kv(k_kv), .k_key(k_key),
                .c_v(cv[c]), .c_kv(ckv[c]), .c_sum(csum[c]), .c_fault(cfl[c]));
        end
    endgenerate
    // the mask travels beside the chunks
    wire [NK-1:0] keep_d;
    ot_hdc_delay #(.W(NK), .D(LAT_C)) u_keep (.clk(clk), .rst_n(rst_n), .d(k_keep), .q(keep_d));
    reg [NK*NCH*32-1:0] tsum;
    reg [NK*NCH-1:0]    tfl;
    integer ci, gi;
    always @* begin
        for (gi = 0; gi < NK; gi = gi + 1)
            for (ci = 0; ci < NCH; ci = ci + 1) begin
                tsum[(gi * NCH + ci) * 32 +: 32] = csum[ci][32 * gi +: 32];
                tfl[gi * NCH + ci] = cfl[ci][gi];
            end
    end
    wire              tv;
    wire [NK-1:0]     tkv, tf;
    wire [NK*16-1:0]  ts;
    ot_hdc_v41x_idx_tail_l #(.NCH(NCH), .NKT(NK), .FPL(FPL)) u_t (.clk(clk), .rst_n(rst_n), .i_v(cv[0]), .i_kv(ckv[0]),
        .i_keep(keep_d), .i_sum(tsum), .i_fault(tfl), .o_v(tv), .o_kv(tkv), .o_score(ts), .o_fault(tf));

    // output FIFO behind a registered output; a beat bypasses the FIFO when it
    // is empty and the output register is free.  Credit: beats in flight plus
    // beats in the FIFO plus the output register stay within FD.
    localparam integer EW = NK * 18;
    localparam integer PW = (FDE <= 2) ? 1 : $clog2(FDE);
    reg [EW-1:0] fm [0:FDE-1];
    reg [CW-1:0] fcnt, infl;
    reg [PW-1:0] wp, rp;
    wire deq = o_valid && o_ready;
    integer ck;
    reg [$clog2(NK+1)-1:0] nk_out, nf_out;
    always @* begin
        nk_out = 0; nf_out = 0;
        for (ck = 0; ck < NK; ck = ck + 1) begin
            nk_out = nk_out + o_kv[ck];
            nf_out = nf_out + (o_kv[ck] & o_fault[ck]);
        end
    end
    always @(posedge clk)
        if (!rst_n) begin
            cnt_keys_scored <= 0; cnt_headsums_fused <= 0; cnt_faults <= 0;
        end else if (deq) begin
            cnt_keys_scored <= cnt_keys_scored + nk_out;
            cnt_headsums_fused <= cnt_headsums_fused + nk_out * IH;
            cnt_faults <= cnt_faults + nf_out;
        end
    wire out_free = !o_valid || o_ready;
    wire from_fifo = (fcnt != 0) && out_free;
    wire bypass = tv && (fcnt == 0) && out_free;
    wire push = tv && !bypass;
    // a q-load beat reaches the query registers 3 edges after it is presented
    // (tile input register, enable register, write); keys wait for it
    reg [1:0] qsettle;
    always @(posedge clk)
        if (!rst_n) qsettle <= 2'd0;
        else if (ql_v) qsettle <= 2'd3;
        else if (qsettle != 0) qsettle <= qsettle - 2'd1;
    assign k_ready = rst_n && !ql_v && (qsettle == 0) && ((infl + fcnt + (o_valid ? 1 : 0)) < FDE);
    always @(posedge clk) begin
        if (!rst_n) begin
            fcnt <= 0; infl <= 0; wp <= 0; rp <= 0; o_valid <= 1'b0;
        end else begin
            infl <= infl + (take ? 1 : 0) - (tv ? 1 : 0);
            if (push) begin
                fm[wp] <= {tf, tkv, ts};
                wp <= (wp == FDE - 1) ? 0 : wp + 1;
            end
            fcnt <= fcnt + (push ? 1 : 0) - (from_fifo ? 1 : 0);
            if (from_fifo) begin
                {o_fault, o_kv, o_score} <= fm[rp];
                rp <= (rp == FDE - 1) ? 0 : rp + 1;
                o_valid <= 1'b1;
            end else if (bypass) begin
                {o_fault, o_kv, o_score} <= {tf, tkv, ts};
                o_valid <= 1'b1;
            end else if (deq) o_valid <= 1'b0;
        end
    end
endmodule

// Full-shape V4.1 index score slice: NK keys/cycle, 32 heads x 128 FP4 dims.
// Reuses the exact chunk8 q4dot/head-sum arithmetic in ot_hdc_v41x_idx_engine_l.
// The output is a ready/valid BF16 score beat with global position metadata,
// suitable for one quarter's selector ingress. No scalar VM score writes.
// Four NK=4 slices per quarter form its 16 score lanes; four quarters need
// sixteen slices. The slice's arithmetic is fully pipelined (II=1 when ready),
// with a finite metadata queue and the engine's own finite output credit.
module ot_hdc_v41x_idx_score_slice_l #(
    parameter integer NK=4, NB=4, IH=32, IW=30, MD=64,
    parameter integer FPL=3, FML=3, QL=3   // engine arithmetic latencies (ot_hdc_v41x_idx_engine_l)
) (
    input wire clk, rst_n,
    input wire ql_v,
    output wire ql_ready,
    input wire [7:0] ql_head,
    input wire [NB*128-1:0] ql_codes,
    input wire [NB*8-1:0] ql_sc,
    input wire [15:0] ql_w,
    input wire i_valid,
    output wire i_ready,
    input wire i_last,
    input wire [IW-1:0] i_first_index,
    input wire [NK-1:0] i_kv,
    input wire [NK-1:0] i_ref,
    input wire [NK-1:0] i_keep,
    input wire [NK*NB*136-1:0] i_key,
    output wire o_valid,
    input wire o_ready,
    output wire o_last,
    output wire [NK-1:0] o_kv,
    output wire [NK*16-1:0] o_score,
    output wire [NK*IW-1:0] o_index,
    output wire [NK-1:0] o_fault
);
    // the engine's key-to-score latency; a queue shallower than it + 4 would
    // throttle the stream, so MD is deepened to the next power of two (no change
    // at FPL = FML = QL = 3: latency 47 at NB = 4, IH = 32)
    localparam integer LVE=(IH/8<=1)?0:$clog2(IH/8);
    localparam integer LATE=(1+QL+FPL*(NB-1)+1+FML+FPL*7+1)+(1+FPL*LVE+1);
    localparam integer MDE=(MD>=LATE+4)?MD:(1<<$clog2(LATE+4));
    localparam integer PW=$clog2(MDE), CW=$clog2(MDE+1);
    reg [IW+NK:0] meta [0:MDE-1]; // {last, first_index, refused mask}
    reg [PW-1:0] wr,rd;
    reg [CW-1:0] count;
    wire ev,er;
    wire [NK-1:0] ekv,ef;
    wire [NK*16-1:0] es;
    wire take=i_valid && i_ready;
    wire pop=o_valid && o_ready;
    // Query SRAM is single-buffered. A new query may overwrite it only after
    // all earlier score beats leave both the engine and metadata queue.
    assign ql_ready=(count==0) && !ev && !i_valid;
    assign i_ready=er && count<MDE;
    assign o_valid=ev && count!=0;
    assign o_last=meta[rd][IW+NK];
    assign o_kv=ekv;
    assign o_fault=ef | meta[rd][NK-1:0];
    wire [IW-1:0] first_index=meta[rd][IW+NK-1:NK];
    genvar g;
    generate for(g=0;g<NK;g=g+1) begin:g_idx
        localparam [IW-1:0] OFFSET=g;
        assign o_index[g*IW +: IW]=first_index+OFFSET;
        assign o_score[g*16 +: 16]=meta[rd][g] ? 16'd0 : es[g*16 +: 16];
    end endgenerate
    ot_hdc_v41x_idx_engine_l #(.NK(NK),.IH(IH),.NB(NB),.FD(MDE),.FPL(FPL),.FML(FML),.QL(QL)) engine (
        .clk(clk),.rst_n(rst_n),.ql_v(ql_v && ql_ready),.ql_head(ql_head),
        .ql_codes(ql_codes),.ql_sc(ql_sc),.ql_w(ql_w),
        .k_valid(take),.k_ready(er),.k_kv(i_kv),.k_keep(i_keep),.k_key(i_key),
        .o_valid(ev),.o_ready(pop),.o_kv(ekv),.o_score(es),.o_fault(ef),
        .cnt_keys_scored(),.cnt_headsums_fused(),.cnt_faults());
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin wr<=0;rd<=0;count<=0;end
        else begin
            if(take) begin
                meta[wr]<={i_last,i_first_index,i_ref};
                wr<=wr+1'b1;
            end
            if(pop) rd<=rd+1'b1;
            case({take,pop})
                2'b10:count<=count+1'b1;
                2'b01:count<=count-1'b1;
                default:count<=count;
            endcase
        end
    end
`ifndef SYNTHESIS
    always @(posedge clk) if(rst_n && ql_v && !ql_ready)
        $fatal(1,"index score query overwrite while prior scores are in flight");
`endif
endmodule

// V4.1 indexer scoring array: NS replicas of one element, the full-geometry
// score slice ot_hdc_v41x_idx_score_slice_l (NK keys x 32 heads x 128 FP4 dims
// per cycle), behind one beat handshake.
//
// Spec instance (results/rtl/w11_idx_array.json): NS=16, NK=4 -> 64 keys/cycle, beat
// aligned with the index reader's 64-key x 544-bit output beat
// (ot_hdc_v41x_idx_shard_quarter_collect: slot 16q+l of a beat is quarter q's
// key l).  Key j of a beat goes to slice j/NK.  Every slice holds its own copy
// of the query registers (the slice's tiles hold them), loaded by one
// broadcast q-load port.
//
// Metadata is per key: global index, candidate keep, reader refusal, slot
// valid; the last tag is per slice (the reader's last tag is per quarter).
// The slice stores the first index of its NK keys and regenerates the others
// as first+g, so the valid keys of one slice group must hold consecutive
// indices -- true of the reader beat, whose 16-key quarter groups are
// consecutive and aligned (NK divides 16).  A violation is a protocol fault.
//
// Handshake: a beat is accepted by all slices in the same cycle (i_ready is
// the AND of the slice readies, every slice sees the accept); a score beat is
// presented when all slices have one and consumed by all together (atomic),
// so the NS*NK scores leave in the beat's slot order.  The slices are
// identical and see identical accept/consume streams, so they stay in step;
// `protocol_fault` flags any divergence (valid or last tags disagreeing).
module ot_hdc_v41x_idx_array_l #(
    parameter integer NS = 16,         // slice replicas
    parameter integer NK = 4,          // keys per slice per cycle
    parameter integer NB = 4,          // 32-blocks per head (index_head_dim/32)
    parameter integer IH = 32,         // index heads
    parameter integer IW = 30,         // global key index width
    parameter integer MD = 64,         // per-slice score/metadata FIFO depth (deepened to cover the latency)
    parameter integer FPL = 3,         // binary32 add latency (7: 1.2 GHz streaming domain)
    parameter integer FML = 3,         // head-weight product latency
    parameter integer QL = 3           // block-dot latency
) (
    input  wire                     clk,
    input  wire                     rst_n,
    // q load, broadcast: one head per cycle
    input  wire                     ql_v,
    output wire                     ql_ready,
    input  wire [7:0]               ql_head,
    input  wire [NB*128-1:0]        ql_codes,
    input  wire [NB*8-1:0]          ql_sc,
    input  wire [15:0]              ql_w,
    // key beat: NS*NK slots
    input  wire                     i_valid,
    output wire                     i_ready,
    input  wire [NS-1:0]            i_last,
    input  wire [NS*NK-1:0]         i_kv,
    input  wire [NS*NK-1:0]         i_ref,
    input  wire [NS*NK-1:0]         i_keep,
    input  wire [NS*NK*IW-1:0]      i_index,
    input  wire [NS*NK*NB*136-1:0]  i_key,
    // score beat to the selector port: NS*NK slots in beat order
    output wire                     o_valid,
    input  wire                     o_ready,
    output wire [NS-1:0]            o_last,
    output wire [NS*NK-1:0]         o_kv,
    output wire [NS*NK-1:0]         o_fault,
    output wire [NS*NK*16-1:0]      o_score,
    output wire [NS*NK*IW-1:0]      o_index,
    output wire                     protocol_fault
);
    localparam integer KW = NB * 136;
    wire [NS-1:0] sr, sv, qr;
    wire take = i_valid && i_ready;
    wire consume = o_valid && o_ready;
    assign i_ready = &sr;
    assign ql_ready = &qr;
    assign o_valid = &sv;
    assign protocol_fault = (|sv && !(&sv)) || ((&sv) && o_last != {NS{o_last[0]}});

    genvar s;
    generate for (s = 0; s < NS; s = s + 1) begin : g_slice
        ot_hdc_v41x_idx_score_slice_l #(.NK(NK), .NB(NB), .IH(IH), .IW(IW), .MD(MD), .FPL(FPL), .FML(FML), .QL(QL)) u (
            .clk(clk), .rst_n(rst_n),
            .ql_v(ql_v), .ql_ready(qr[s]), .ql_head(ql_head),
            .ql_codes(ql_codes), .ql_sc(ql_sc), .ql_w(ql_w),
            .i_valid(take), .i_ready(sr[s]), .i_last(i_last[s]),
            .i_first_index(i_index[s*NK*IW +: IW]),
            .i_kv(i_kv[s*NK +: NK]), .i_ref(i_ref[s*NK +: NK]), .i_keep(i_keep[s*NK +: NK]),
            .i_key(i_key[s*NK*KW +: NK*KW]),
            .o_valid(sv[s]), .o_ready(consume), .o_last(o_last[s]),
            .o_kv(o_kv[s*NK +: NK]), .o_fault(o_fault[s*NK +: NK]),
            .o_score(o_score[s*NK*16 +: NK*16]),
            .o_index(o_index[s*NK*IW +: NK*IW]));
    end endgenerate

`ifndef SYNTHESIS
    // consecutive indices inside each slice group (valid slots only)
    integer cs, cg;
    always @(posedge clk) if (rst_n && take)
        for (cs = 0; cs < NS; cs = cs + 1)
            for (cg = 1; cg < NK; cg = cg + 1)
                if (i_kv[cs*NK + cg] &&
                    i_index[(cs*NK + cg)*IW +: IW] != i_index[cs*NK*IW +: IW] + cg)
                    $fatal(1, "idx array: slice %0d slot %0d index not consecutive", cs, cg);
    always @(posedge clk) if (rst_n && protocol_fault)
        $fatal(1, "idx array: slices out of step");
`endif
endmodule
